[CmdletBinding()]
param(
    [string]$JavaHome = '',
    [string]$MavenHome = '',
    [string]$PostgresImage = 'postgres:17'
)
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$containerId = $null
$oldJavaHome = $env:JAVA_HOME
$oldPath = $env:Path
$oldDbUrl = $env:SH_QA_DB_URL
$oldDbPassword = $env:SH_QA_DB_PASSWORD
$report = Join-Path $root 'target\facebook-qa-report.txt'
$temp = Join-Path ([System.IO.Path]::GetTempPath()) ('socialhub-fbqa-' + [guid]::NewGuid().ToString('N'))
$success = $false
Push-Location $root
try {
    if (!(Test-Path (Join-Path $root 'pom.xml') -PathType Leaf)) {
        throw 'pom.xml not found. Copy the QA script to the Backend project root.'
    }
    $maven = $null
    if ($MavenHome) {
        $maven = Join-Path $MavenHome 'bin\mvn.cmd'
        if (!(Test-Path $maven -PathType Leaf)) { throw 'Invalid MavenHome: bin\mvn.cmd not found.' }
    } elseif (Test-Path (Join-Path $root 'mvnw.cmd') -PathType Leaf) {
        $maven = Join-Path $root 'mvnw.cmd'
    } else {
        $command = Get-Command mvn.cmd -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($command) { $maven = $command.Source }
        if (!$maven) {
            foreach ($homePath in @($env:MAVEN_HOME, $env:M2_HOME)) {
                if ($homePath) {
                    $candidateMaven = Join-Path $homePath 'bin\mvn.cmd'
                    if (Test-Path $candidateMaven -PathType Leaf) { $maven = $candidateMaven; break }
                }
            }
        }
        if (!$maven -and $env:ProgramFiles) {
            $jetbrains = Join-Path $env:ProgramFiles 'JetBrains'
            $installations = Get-ChildItem -Path $jetbrains -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -like 'IntelliJ IDEA*' } | Sort-Object Name -Descending
            foreach ($installation in $installations) {
                $candidateMaven = Join-Path $installation.FullName 'plugins\maven\lib\maven3\bin\mvn.cmd'
                if (Test-Path $candidateMaven -PathType Leaf) { $maven = $candidateMaven; break }
            }
        }
    }
    if (!$maven) { throw 'Maven not found. Run with -MavenHome pointing to a Maven installation (including IntelliJ bundled Maven).' }
    Write-Host "Maven: $maven"
    if (!(Test-Path (Join-Path $root 'src\main\resources\db\migration\V41__facebook_identity_sync_queue.sql'))) {
        throw 'V41 is missing from this source. Do not run until the correct source is available.'
    }
    if (!$JavaHome) {
        $candidate = Get-ChildItem -Path (Join-Path $HOME '.jdks') -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -like 'openjdk-25*' -and (Test-Path (Join-Path $_.FullName 'bin\javac.exe')) } |
            Sort-Object Name -Descending | Select-Object -First 1
        if ($candidate) { $JavaHome = $candidate.FullName }
    }
    if ($JavaHome) {
        if (!(Test-Path (Join-Path $JavaHome 'bin\javac.exe'))) { throw 'Invalid JavaHome.' }
        $env:JAVA_HOME = $JavaHome
        $env:Path = (Join-Path $JavaHome 'bin') + ';' + $env:Path
    } elseif ($env:JAVA_HOME -and (Test-Path (Join-Path $env:JAVA_HOME 'bin\javac.exe'))) {
        $env:Path = (Join-Path $env:JAVA_HOME 'bin') + ';' + $env:Path
    }
    $javac = (Get-Command javac.exe -ErrorAction Stop).Source
    $java = Join-Path (Split-Path $javac -Parent) 'java.exe'
    $version = (& $javac -version | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $version -notmatch '^javac 25(?:\.|\s|$)') { throw "JDK 25 required. Found: $version. Use -JavaHome." }
    & docker info --format '{{.ServerVersion}}'
    if ($LASTEXITCODE -ne 0) { throw 'Docker Desktop is not running.' }
    New-Item -ItemType Directory -Force $temp | Out-Null
    # Embedded QA source from the original isolated QA bundle.
    $qaSource = Join-Path $temp 'FacebookMultiAccountQa.java'
    $qaSourceBase64 = ''
    [System.IO.File]::WriteAllBytes($qaSource, [System.Convert]::FromBase64String($qaSourceBase64))
    Write-Host 'Embedded QA Java source ready.'
    $cpFile = Join-Path $temp 'classpath.txt'
    $classes = Join-Path $temp 'classes'
    New-Item -ItemType Directory -Force $classes | Out-Null
    Write-Host '[1/4] Compile existing Backend and resolve runtime dependencies. No Spring Boot start.'
    & $maven -DskipTests compile dependency:build-classpath '-DincludeScope=runtime' "-Dmdep.outputFile=$cpFile"
    if ($LASTEXITCODE -ne 0 -or !(Test-Path $cpFile)) { throw 'Maven compile/classpath failed.' }
    $cp = (Join-Path $root 'target\classes') + ';' + (Get-Content $cpFile -Raw).Trim()
    & $javac -encoding UTF-8 -cp $cp -d $classes $qaSource
    if ($LASTEXITCODE -ne 0) { throw 'QA harness compilation failed.' }
    Write-Host '[2/4] Start a dedicated disposable PostgreSQL container (random localhost port).'
    $name = 'socialhub-fbqa-' + [guid]::NewGuid().ToString('N').Substring(0,12)
    $password = [guid]::NewGuid().ToString('N') + [guid]::NewGuid().ToString('N')
    $rawId = & docker run --rm -d --name $name -e 'POSTGRES_USER=qa_runner' -e "POSTGRES_PASSWORD=$password" -e 'POSTGRES_DB=socialhub_multi_account_qa' -p '127.0.0.1::5432' $PostgresImage
    if ($LASTEXITCODE -ne 0) { throw 'Unable to create isolated QA database.' }
    $containerId = ($rawId | Out-String).Trim()
    if ($containerId -notmatch '^[a-f0-9]{64}$') { throw 'Unexpected Docker container ID.' }
    $ready = $false
    for ($i = 0; $i -lt 90; $i++) {
        & docker exec $containerId pg_isready -h 127.0.0.1 -U qa_runner -d socialhub_multi_account_qa | Out-Null
        if ($LASTEXITCODE -eq 0) { $ready = $true; break }
        Start-Sleep -Seconds 1
    }
    if (!$ready) { throw 'QA PostgreSQL did not become ready.' }
    $portOutput = (& docker port $containerId '5432/tcp' | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $portOutput -notmatch '^127\.0\.0\.1:(\d+)$') { throw 'Expected a dedicated loopback-only Docker port.' }
    $port = $Matches[1]
    $env:SH_QA_DB_URL = "jdbc:postgresql://127.0.0.1:$port/socialhub_multi_account_qa"
    $env:SH_QA_DB_PASSWORD = $password
    Write-Host '[3/4] Run real Flyway migrations, queue and claim tests with fake provider responses.'
    & $java '-Dfile.encoding=UTF-8' '-Dsun.stdout.encoding=UTF-8' -cp "$classes;$cp" com.socialhub.facebookoauth.service.implement.FacebookMultiAccountQa 2>&1 | Tee-Object -FilePath $report
    if ($LASTEXITCODE -ne 0) { throw "QA failed. See $report" }
    $success = $true
} finally {
    Write-Host '[4/4] Clean up only this QA container and temporary compilation files.'
    if ($containerId -and $containerId -match '^[a-f0-9]{64}$') {
        & docker rm -f $containerId | Out-Null
        if ($LASTEXITCODE -ne 0) { Write-Warning "Could not remove QA container $containerId. Remove only this container manually." }
    }
    if (Test-Path $temp) { Remove-Item -Recurse -Force $temp }
    $env:JAVA_HOME = $oldJavaHome
    $env:Path = $oldPath
    $env:SH_QA_DB_URL = $oldDbUrl
    $env:SH_QA_DB_PASSWORD = $oldDbPassword
    Pop-Location
}
if ($success) { Write-Host "PASS. Report: $report" -ForegroundColor Green }
